/// Inner loop for prompt_yes_no, factored out so the caller can
/// guarantee cursor cleanup regardless of how control exits.
fn prompt_yes_no_loop(
    term: &Term,
    options: &[PromptOption],
    sel: &mut usize,
    pad: &str,
    active_prefix: &Style,
